import React, { useEffect, useRef, memo } from 'react';

// ── Symbol mapping: our coin symbols → TradingView BINANCE pairs ───────────
const TV_SYMBOL_MAP = {
  BTC:   'BINANCE:BTCUSDT',
  ETH:   'BINANCE:ETHUSDT',
  SOL:   'BINANCE:SOLUSDT',
  BNB:   'BINANCE:BNBUSDT',
  XRP:   'BINANCE:XRPUSDT',
  DOGE:  'BINANCE:DOGEUSDT',
  ADA:   'BINANCE:ADAUSDT',
  AVAX:  'BINANCE:AVAXUSDT',
  DOT:   'BINANCE:DOTUSDT',
  POL:   'BINANCE:MATICUSDT',
  MATIC: 'BINANCE:MATICUSDT',
  LINK:  'BINANCE:LINKUSDT',
  UNI:   'BINANCE:UNIUSDT',
  ATOM:  'BINANCE:ATOMUSDT',
  LTC:   'BINANCE:LTCUSDT',
  NEAR:  'BINANCE:NEARUSDT',
  APT:   'BINANCE:APTUSDT',
  ARB:   'BINANCE:ARBUSDT',
  OP:    'BINANCE:OPUSDT',
  TON:   'BINANCE:TONUSDT',
  SHIB:  'BINANCE:SHIBUSDT',
  IMX:   'BINANCE:IMXUSDT',
  BLUR:  'BINANCE:BLURUSDT',
  SEI:   'BINANCE:SEIUSDT',
  SUI:   'BINANCE:SUIUSDT',
  ALGO:  'BINANCE:ALGOUSDT',
  FIL:   'BINANCE:FILUSDT',
  XMR:   'BINANCE:XMRUSDT',
  AAVE:  'BINANCE:AAVEUSDT',
  MKR:   'BINANCE:MKRUSDT',
  CRV:   'BINANCE:CRVUSDT',
  LDO:   'BINANCE:LDOUSDT',
  DYDX:  'BINANCE:DYDXUSDT',
  INJ:   'BINANCE:INJUSDT',
  STX:   'BINANCE:STXUSDT',
  TIA:   'BINANCE:TIAUSDT',
  WIF:   'BINANCE:WIFUSDT',
  PEPE:  'BINANCE:PEPEUSDT',
  BONK:  'BINANCE:BONKUSDT',
  FLOKI: 'BINANCE:FLOKIUSDT',
  TAO:   'BINANCE:TAOUSDT',
  KAS:   'BINANCE:KASUSDT',
  PENDLE:'BINANCE:PENDLEUSDT',
  RNDR:  'BINANCE:RNDRUSDT',
  FET:   'BINANCE:FETUSDT',
  WLD:   'BINANCE:WLDUSDT',
  JUP:   'BINANCE:JUPUSDT',
  JTO:   'BINANCE:JTOUSDT',
  PYTH:  'BINANCE:PYTHUSDT',
  AR:    'BINANCE:ARUSDT',
  GALA:  'BINANCE:GALAUSDT',
  AXS:   'BINANCE:AXSUSDT',
  SAND:  'BINANCE:SANDUSDT',
  MANA:  'BINANCE:MANAUSDT',
  CAKE:  'BINANCE:CAKEUSDT',
  '1INCH':'BINANCE:1INCHUSDT',
  LRC:   'BINANCE:LRCUSDT',
  BAT:   'BINANCE:BATUSDT',
  CHZ:   'BINANCE:CHZUSDT',
  ZIL:   'BINANCE:ZILUSDT',
  ENJ:   'BINANCE:ENJUSDT',
  VET:   'BINANCE:VETUSDT',
  THETA: 'BINANCE:THETAUSDT',
  XTZ:   'BINANCE:XTZUSDT',
  NEO:   'BINANCE:NEOUSDT',
  QTUM:  'BINANCE:QTUMUSDT',
  ICX:   'BINANCE:ICXUSDT',
  EGLD:  'BINANCE:EGLDUSDT',
  ICP:   'BINANCE:ICPUSDT',
  ETC:   'BINANCE:ETCUSDT',
  XLM:   'BINANCE:XLMUSDT',
  TRX:   'BINANCE:TRXUSDT',
  SNX:   'BINANCE:SNXUSDT',
  COMP:  'BINANCE:COMPUSDT',
  YFI:   'BINANCE:YFIUSDT',
  BAL:   'BINANCE:BALUSDT',
  OKB:   'BINANCE:OKBUSDT',
  STORJ: 'BINANCE:STORJUSDT',
  NMR:   'BINANCE:NMRUSDT',
  OCEAN: 'BINANCE:OCEANUSDT',
  ACH:   'BINANCE:ARUSDT',
};

const getTVSymbol = (symbol) => TV_SYMBOL_MAP[symbol] || `BINANCE:${symbol}USDT`;

// ── TradingView Widget Component ──────────────────────────────────────────
function TradingViewChart({ symbol = 'BTC', coinColor = '#3b82f6', coinName = 'Bitcoin' }) {
  const containerRef = useRef(null);
  const widgetRef    = useRef(null);
  const scriptRef    = useRef(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    // Clean up previous widget
    container.innerHTML = '';
    if (scriptRef.current) {
      scriptRef.current.remove();
      scriptRef.current = null;
    }

    const containerId = `tv_chart_${symbol}_${Date.now()}`;
    const wrapper = document.createElement('div');
    wrapper.id = containerId;
    wrapper.style.width  = '100%';
    wrapper.style.height = '100%';
    container.appendChild(wrapper);

    const script = document.createElement('script');
    script.src   = 'https://s3.tradingview.com/tv.js';
    script.async = true;
    script.onload = () => {
      if (!window.TradingView || !container) return;
      widgetRef.current = new window.TradingView.widget({
        autosize:          true,
        symbol:            getTVSymbol(symbol),
        interval:          'D',
        timezone:          'Etc/UTC',
        theme:             'dark',
        style:             '1',           // 1 = candles, 2 = bars, 3 = line, etc.
        locale:            'en',
        toolbar_bg:        '#0d1526',
        enable_publishing: false,
        allow_symbol_change: true,
        hide_top_toolbar:  false,
        hide_legend:       false,
        save_image:        false,
        container_id:      containerId,
        studies: [
          'MASimple@tv-basicstudies',
          'RSI@tv-basicstudies',
          'MACD@tv-basicstudies',
          'BB@tv-basicstudies',
          'Volume@tv-basicstudies',
        ],
        overrides: {
          'paneProperties.background':           '#04070d',
          'paneProperties.backgroundType':       'solid',
          'paneProperties.vertGridProperties.color': 'rgba(255,255,255,0.04)',
          'paneProperties.horzGridProperties.color': 'rgba(255,255,255,0.04)',
          'scalesProperties.textColor':           '#4a5e78',
          'mainSeriesProperties.candleStyle.upColor':           '#00e5b3',
          'mainSeriesProperties.candleStyle.downColor':         '#f03e55',
          'mainSeriesProperties.candleStyle.wickUpColor':       '#00e5b3',
          'mainSeriesProperties.candleStyle.wickDownColor':     '#f03e55',
          'mainSeriesProperties.candleStyle.borderUpColor':     '#00e5b3',
          'mainSeriesProperties.candleStyle.borderDownColor':   '#f03e55',
        },
      });
    };

    scriptRef.current = script;
    document.head.appendChild(script);

    return () => {
      if (container) container.innerHTML = '';
      // Note: don't remove the script — TradingView widget script is cached
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [symbol]);

  return (
    <div style={{
      width: '100%', height: '100%',
      position: 'relative',
      background: '#04070d',
    }}>
      <div ref={containerRef} style={{ width: '100%', height: '100%' }} />
    </div>
  );
}

export default memo(TradingViewChart);
